@startuml

class Person {
  + Name : string
  + Email : string
}

class Student extends Person {}

class Tutor extends Person {
  + BankAccount : string
}

class Subject {
  + Name : string
}

class TutoringOffer {
  + LevelOfExpertise : string
  + HourlyPrice : float
}

class Availability {
  + DayOfWeek : string
  + StartTime : time
  + EndTime : time
}

class TutoringRequest {
  + RequestedLevel : string
  + TargetDateTime : datetime
}

class TutoringSession {
  + ActualDateTime : datetime
  + Status : string
}

class Payment {
  + Amount : float
  + Method : string
}

Tutor "1" -- "*" TutoringOffer : offers
Tutor "1" -- "*" Availability : specifies
Tutor "1" -- "*" TutoringOffer : subject
Subject "1" -- "*" TutoringOffer : categorized by
Subject "1" -- "*" Tutor : subject of award

Student "1" -- "*" TutoringRequest : makes
Tutor "1" -- "*" TutoringRequest : receives
TutoringRequest "1" -- "0..1" TutoringSession : becomes

TutoringSession "*" -- "1" Student : attended by
TutoringSession "*" -- "1" Tutor : conducted by

TutoringSession "1" -- "0..1" Payment : results in

@enduml

